// Temporary manual capture route only. Not a regression or part of STABLE_SCENARIOS.
async (page, { openPath }) => {
  const out = 'docs/design/assets/ui-patterns-777';
  const loaded = await (await page.request.get(page.url().split('/').slice(0,3).join('/')+'/api/document')).json();
  const sep = loaded.path.includes('\\') ? '\\' : '/';
  const root = loaded.path.split(sep).slice(0,-4).join(sep);
  await page.setViewportSize({width:1440,height:900});
  await page.evaluate(() => { localStorage.setItem('litzio.theme','light'); localStorage.setItem('litzio.language','en'); });
  await page.reload();
  const shots=[];
  const active=()=>page.locator('[data-document-tab][data-active=true]');
  const settle=async()=>{await page.evaluate(async()=>{await document.fonts.ready; await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));});};
  const shot=async(name, target)=>{
    await settle();
    await page.screenshot({path:`${out}/${name}.png`});
    if(target) { const b=await target.boundingBox(); const clip={x:Math.max(0,b.x-18),y:Math.max(73,b.y-24),width:Math.min(1440, b.x+b.width+18)-Math.max(0,b.x-18),height:Math.min(900,b.y+b.height+18)-Math.max(73,b.y-24)}; await page.screenshot({path:`${out}/${name}-crop.png`,clip}); }
    shots.push(name);
  };
  const open=async(name='inventory.md')=>{await openPath(page,[root,'tmp','ui-patterns-777',name].join(sep)); await settle();};
  await open();
  await shot('01-document-rest',active().locator('article.document'));
  await active().getByRole('button',{name:'Document settings',exact:true}).click();
  await shot('02-document-settings',active().locator('.document-settings'));
  await active().getByRole('button',{name:'Document settings',exact:true}).click();
  const eq=active().locator('.equation').first();
  await eq.evaluate(el=>el.scrollIntoView({block:'center'})); await page.mouse.move(0,0); await shot('03-equation-rest',eq);
  await eq.hover(); await shot('04-equation-hover',eq);
  await eq.getByRole('button',{name:'Edit',exact:true}).click();
  await shot('05-equation-form',eq);
  await page.getByTestId('equation-cancel').click();
  const table=active().locator('.table-block').first();
  await table.evaluate(el=>el.scrollIntoView({block:'center'})); await table.hover();
  await shot('06-table-tools',table);
  await table.getByRole('button',{name:'Edit table',exact:true}).click();
  await shot('07-table-form',page.getByTestId('table-properties'));
  await page.getByTestId('table-label').fill('eq-example'); await page.getByTestId('table-apply').click();
  await shot('08-table-error',page.getByTestId('table-properties'));
  await page.getByTestId('table-cancel').click();
  const fig=active().locator('.figure').filter({has:page.getByTestId('figure-image')}).first();
  await fig.evaluate(el=>el.scrollIntoView({block:'center'})); await page.mouse.move(0,0); await shot('09-figure-rest',fig);
  await fig.hover(); await shot('10-figure-hover',fig);
  await fig.getByRole('button',{name:'Edit figure',exact:true}).click();
  await shot('11-figure-form',page.getByTestId('figure-properties'));
  await page.getByTestId('figure-editor').getByRole('button',{name:'Fixed',exact:true}).click();
  await page.getByTestId('figure-enumerator').fill('S1');
  await shot('12-figure-fixed',page.getByTestId('figure-properties'));
  await page.getByTestId('figure-label').press('Escape');
  const mer=active().locator('[data-content-kind=mermaid]').first();
  await mer.scrollIntoViewIfNeeded(); await mer.hover();
  await mer.getByRole('button',{name:'Edit figure',exact:true}).click();
  await page.getByTestId('mermaid-property-editor').locator('.figure-property-thumbnail img').waitFor();
  await shot('13-mermaid-properties',page.getByTestId('mermaid-property-properties'));
  await page.getByTestId('mermaid-edit-source').click();
  await page.getByTestId('mermaid-edit-preview').locator('img').waitFor();
  await page.getByTestId('mermaid-edit-preview').evaluate(async el=>{await el.querySelector('img').decode();});
  await page.getByTestId('mermaid-properties').evaluate(el=>el.scrollIntoView({block:'center'}));
  await shot('14-mermaid-source',page.getByTestId('mermaid-properties'));
  await page.getByTestId('mermaid-cancel').click();
  const note=active().getByTestId('footnote-definition').first();
  await note.scrollIntoViewIfNeeded(); await page.mouse.move(0,0); await shot('15-endnote-rest',note);
  await note.getByTestId('endnote-edit').click(); await shot('16-endnote-edit',note);
  await note.getByTestId('endnote-cancel').click();
  await active().getByTestId('label-target-edit').first().scrollIntoViewIfNeeded();
  await active().locator('h1').first().hover();
  await active().getByTestId('label-target-edit').first().click();
  await shot('17-section-label',page.getByTestId('label-target-properties'));
  await page.getByTestId('label-target-cancel').click();
  const cite=active().locator('[data-citation]').first(); await cite.hover(); await cite.getByTestId('citation-edit').click();
  await shot('18-citation-form',page.getByTestId('citation-form')); await page.keyboard.press('Escape');
  const ref=active().getByTestId('cross-reference').first(); await ref.hover(); await ref.getByTestId('cross-reference-edit').click();
  await shot('19-reference-form',page.getByTestId('reference-form')); await page.keyboard.press('Escape');
  await active().locator('.inline-math-rendered .katex-html').first().dblclick();
  await shot('20-inline-math',page.getByTestId('inline-math-properties')); await page.getByTestId('inline-math-cancel').click();
  await active().locator('.document-editor').evaluate(el=>{
    const editor=el.editor; let range;
    editor.state.doc.descendants((node,pos)=>{if(node.isText && node.text.includes('design resource')) {const from=pos+node.text.indexOf('design resource');range={from,to:from+'design resource'.length};}});
    editor.chain().focus().setTextSelection(range).run();
  });
  await page.getByTestId('selection-toolbar').waitFor();
  await shot('37-selection-toolbar',page.getByTestId('selection-toolbar'));
  await page.keyboard.press("Control+Quote");
  await shot('21-link-form',page.getByTestId('link-form')); await page.getByTestId('link-url').fill('bad url'); await page.getByTestId('link-apply').click();
  await shot('22-link-error',page.getByTestId('link-form')); await page.keyboard.press('Escape');
  await page.mouse.move(0,0); await active().getByTestId('footnote-reference').first().hover();
  await page.getByTestId('reference-preview').waitFor(); await shot('23-endnote-preview',page.getByTestId('reference-preview'));
  await page.mouse.move(0,0); await cite.hover(); await page.getByTestId('reference-preview').waitFor(); await shot('24-citation-preview',page.getByTestId('reference-preview'));
  await page.mouse.move(0,0); await active().locator('a[href="diagram.svg"]').hover(); await page.getByTestId('image-link-preview').waitFor(); await shot('25-image-preview',page.getByTestId('image-link-preview'));
  await open('empty.md'); await shot('26-empty-title',active().locator('.document-title-input'));
  for(const [name,selector] of [['27-empty-figure','.figure'],['28-empty-table','.table-block'],['29-pending-figure','.figure:has([data-testid=figure-no-content])']]) {const el=active().locator(selector).first();await el.scrollIntoViewIfNeeded(); await page.mouse.move(0,0); await shot(name,el);}
  await open('warnings.md');
  await shot('30-numbering-notice',active().getByTestId('numbering-warnings'));
  const missing=active().locator('.figure').nth(1);await missing.scrollIntoViewIfNeeded(); await missing.hover();
  await missing.getByRole('button',{name:'Edit figure',exact:true}).click();
  await shot('31-numbering-warning',page.getByTestId('figure-properties'));await page.getByTestId('figure-label').press('Escape');
  await open();
  await page.getByRole('button',{name:'File actions',exact:true}).click();
  await shot('32-file-menu',page.getByRole('menu'));await page.keyboard.press('Escape');
  await page.getByRole('button',{name:'New document…',exact:true}).click();
  await shot('33-new-dialog',page.getByRole('dialog'));await page.keyboard.press('Escape');
  await page.getByRole('button',{name:'Settings',exact:true}).click();
  await shot('34-settings',page.getByTestId('settings-dialog'));
  await page.getByTestId('theme').selectOption('dark');await page.getByTestId('settings-back').click();
  const darkFig=active().locator('.figure').filter({has:page.getByTestId('figure-image')}).first();await darkFig.scrollIntoViewIfNeeded();await darkFig.hover();
  await darkFig.getByRole('button',{name:'Edit figure',exact:true}).click();
  await shot('35-figure-dark',page.getByTestId('figure-properties'));await page.getByTestId('figure-label').press('Escape');
  await page.getByRole('button',{name:'Settings',exact:true}).click();await page.getByTestId('theme').selectOption('light');await page.getByTestId('settings-back').click();
  await active().locator('.document-title-input').fill('Unsaved example');
  await page.getByRole('button',{name:'Close inventory.md',exact:true}).click();
  await shot('36-unsaved-dialog',page.getByRole('dialog'));await page.getByRole('button',{name:'Cancel',exact:true}).click();
  return {purpose:'Manual inventory capture only; no product behavior verdict',viewport:[1440,900],shots};
}
